    q6912: { h: "07888068a6f3", text: "Pointing out the belt and the door to every passenger before the flight: would you enjoy this ritual of pointing out?" },
    q6913: { h: "ce06ec887b43", text: "The flight only after counting the weight distribution of the loaded goods again: does this firmness on counting appeal to you?" },
    q6914: { h: "313c2ed25b57", text: "No worker may go onto the runway without a bright vest: would you keep up this vest rule?" },
    q6915: { h: "21c15eb11004", text: "Matching the count of tools put into the engine after the work: would you accept this matching of the count?" },
    q6916: { h: "dfd27351729a", text: "Connecting a wire to the ground to discharge electricity while fuelling: will you keep this rule of the earth wire?" },
    q6917: { h: "9ad1ca371be6", text: "Always bending low and going from the front under a slowing rotor: would you enjoy this ritual of bending low?" },
    q6918: { h: "80b0df266fb5", text: "The checklist of propellers and battery before flying: does this ritual of the list appeal to you?" },
    q6919: { h: "7862f43cc6df", text: "Not the slightest slack allowed in counting the distance between two aircraft: would you keep up this ban on slack?" },
    q6920: { h: "eaefd049877a", text: "Not touching the instruments in flying lessons without the teacher present: would you accept this rule of presence?" },
    q6921: { h: "23fda07e15c3", text: "Getting every passenger to fasten the belt even in a small aircraft: will you keep this ritual of the belt?" },
    q6922: { h: "2a6c9794f1d1", text: "A daily eye so that the high stack of goods does not lean crooked: would you enjoy this habit of the eye?" },
    q6923: { h: "1a8aac349380", text: "Testing every shift that the door of the icy room opens from the inside too: does this test appeal to you?" },
    q6924: { h: "f0b45c494629", text: "Going down into the grain pit alone is forbidden, a rope and a companion are a must: would you keep up this rope rule?" },
    q6925: { h: "5c277325f2fe", text: "A lock and a warning board on the gas fumigation room for the fixed hours: would you accept this lock and board?" },
    q6926: { h: "df6fcec81a3c", text: "Looking at delivery addresses and numbers only as far as the work needs, and passing them to no one: would you accept this limit?" },
    q6927: { h: "031714f85acb", text: "The order of keeping goods with the earlier expiry date in front: would you enjoy this rule of order?" },
    q6928: { h: "cff5ed7ca1fa", text: "Keeping goods that arrive with a broken seal aside and writing a slip: does this rule of the separate slip appeal to you?" },
    q6929: { h: "0c7ee54c5f8e", text: "Not sending dangerous goods without making sure of the separate label: would you keep up this firmness on labels?" },
    q6930: { h: "bd75c5028e19", text: "Keeping the fire hose and the exit door of the warehouse always clear: would you accept this habit of the clear door?" },
