    q12592: { h: "c2c5ad1e0e95", text: "The materials of a passenger rail service are coach parts and electric traction: would you understand coach maintenance?" },
    q12593: { h: "ab5176868300", text: "A freight rail service takes wagon slots and seal locks: would you enjoy the seal mark?" },
