    q16433: { h: "2c3f062abf43", text: "A pharma cold van means a run against the clock with the ice box: would you enjoy ice against the clock?" },
    q17332: { h: "538fadbf34f0", text: "Truck freight swings with the mandi and the season: could you bear the swing of freight?" },
    q17333: { h: "3debd3f2daaa", text: "The permit for a bus route goes round offices for months: could you put up with the round of permits?" },
